let s;try{s=JSON.parse(localStorage.getItem('hotseat-v1'));if(s?.version!==1)s=null;}catch{}s=s||Game.fresh();let tab='office',notice='';const $=q=>document.querySelector(q),round=n=>Math.round(n),money=n=>'$'+n+'M';function save(){try{localStorage.setItem('hotseat-v1',JSON.stringify(s));}catch{notice='Browser storage unavailable. Keep this tab open to preserve your run.';}}
function chair(){return `<svg viewBox="0 0 240 190" role="img" aria-label="Hot seat at ${round(s.heat)} percent"><defs><linearGradient id="flame" x2="0" y2="1"><stop stop-color="#ffc76b"/><stop offset="1" stop-color="#fb562e"/></linearGradient></defs><ellipse cx="120" cy="170" rx="80" ry="12" fill="#ea6420" opacity=".12"/>${s.heat>15?`<g class="flames" opacity="${.3+s.heat/150}"><path d="M58 155 Q20 110 61 61 Q53 105 84 93 Q80 49 116 ${Math.max(0,68-s.heat)} Q107 65 140 86 Q159 67 164 43 Q205 110 175 155Z" fill="url(#flame)"/><path d="M87 156 Q65 127 91 99 Q88 124 113 113 Q114 79 130 66 Q126 117 150 119 Q170 144 151 159Z" fill="#ffcf70"/></g>`:''}<g stroke="#131b1c" stroke-width="5" stroke-linejoin="round"><path d="M87 139 L79 177 M155 139 L164 177" stroke="#a5a7a0" stroke-width="9"/><rect x="75" y="60" width="91" height="71" rx="14" fill="#52615b"/><path d="M87 72h65v46H87z" fill="#65756c" stroke-width="2"/><rect x="69" y="125" width="105" height="23" rx="8" fill="#8a9a87"/><path d="M65 105v28m113-28v28" stroke="#a5a7a0" stroke-width="8"/><path d="M53 103h27m85 0h26" stroke="#b7bbae" stroke-width="9"/></g></svg>`;}
function button(text,action,disabled=false,cls=''){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;}
function render(){let u=Game.units(s),t=s.teams[0],pick=Game.draftOrder(s).findIndex(t=>!t.id)+1,status=s.heat<25?'SECURE':s.heat<50?'WARM':s.heat<75?'HOT':'CRITICAL';$('#app').innerHTML=`<header><a class="brand" href="#" aria-label="Hot Seat home"><span class="brand-mark">H<span>+</span></span>HOT SEAT<span class="edition">FRONT OFFICE / 01</span></a><div class="header-actions"><span class="saved">● AUTO-SAVED</span>${button('How to play','help')}${button('New run','reset')}</div></header><main><div class="title-row"><div><div class="eyebrow">THE REBUILD STARTS HERE</div><h1>Rust City <span>Hounds.</span></h1><p>A bad roster. A short leash. One shot at a championship.</p></div><div class="season">SEASON <b>${String(s.season).padStart(2,'0')}</b><span>${s.phase==='regular'?`WEEK ${s.week+1} OF 10`:s.phase.toUpperCase()}</span></div></div><div class="stats"><div><label>SEASON RECORD</label><strong>${t.w}<i>–</i>${t.l}</strong><small>${Game.standings(s).findIndex(t=>!t.id)+1} / 16 in the league</small></div><div><label>PROJECTED DRAFT PICK</label><strong>#${pick}</strong><small>Worst record picks first</small></div><div><label>AVAILABLE BUDGET</label><strong>${money(s.cash)}</strong><small>${money(s.budget)} annual funding</small></div><div><label>TEAM OVERALL</label><strong>${round(u.overall)}<em>/ 99</em></strong><small>OFF ${round(u.off)} <span>·</span> DEF ${round(u.def)}</small></div></div><nav>${[['office','Front office'],['roster','Roster & development'],['market','Free agency'],['league','League & draft race']].map(([id,label])=>button(label,'tab:'+id,false,tab===id?'active':'')).join('')}</nav>${notice?`<div class="notice" role="status">${notice}</div>`:''}<div class="layout"><section>${s.phase==='fired'||s.phase==='champion'?ending():s.phase==='draft'?draftView():tab==='office'?office():tab==='roster'?roster():tab==='market'?market():league()}</section><aside><div class="panel seat"><div class="panel-label">JOB SECURITY <span class="pill ${s.heat>=75?'danger':''}">${status}</span></div>${chair()}<div class="heat-number">${round(s.heat)}<span> / 100 HEAT</span></div><div class="heat-track"><span style="width:${s.heat}%"></span></div><p>${s.heat<50?'You have room to build. Make it count.':s.heat<75?'Ownership needs a reason to believe.':'Your next decisions could cost you the job.'}</p><div class="review-note">OWNER EXPECTATION <b>${Math.min(6,s.season+1)} wins this season</b><small class="grace-note">${Game.scrutiny(s)<1?"PATIENCE GRADUALLY FADING":"FULL SCRUTINY"}<br>${round(Game.scrutiny(s)*100)}% of normal heat gains. Wins cool normally.</small><small>100 heat ends your run.</small></div></div><div class="panel pulse"><div class="panel-label">FRANCHISE PULSE</div>${[['Locker room',s.morale],['Fan confidence',s.fans]].map(([n,v])=>`<div class="pulse-row"><span>${n}</span><b>${round(v)}%</b></div><div class="mini-track"><span style="width:${v}%"></span></div>`).join('')}<div class="funding">NEXT YEAR’S FUNDING<b>${money(80+t.w*2+s.bonus+Math.floor(s.fans/10))}</b><small>$80M base + wins + fans + playoff bonuses</small></div></div></aside></div><footer><span>HOT SEAT <b> / </b> LOSE WITH A PURPOSE.</span><span>Local save · Fictional league · MVP 0.1</span></footer></main>`;}
function office(){let pair=s.schedule[Math.min(s.week,9)].find(p=>p.includes(0)),opp=s.phase==='playoffs'?Game.standings(s).filter(t=>t.id!==0).slice(0,5)[Math.max(0,4-s.playoffRound*2)]:s.teams[pair.find(id=>id!==0)],u=Game.units(s);return `<div class="panel matchup"><div class="panel-label">${s.phase==='regular'?'NEXT MATCHUP':'POSTSEASON'}<span class="live-dot">● ${s.phase==='regular'?'GAME DAY':'SEASON '+s.season}</span></div><div class="versus"><div><div class="team-logo hounds">H</div><h3>RUST CITY</h3><small>HOUNDS · ${s.teams[0].w}–${s.teams[0].l}</small></div><div class="vs">VS<span>${s.phase==='regular'?'WEEK '+(s.week+1):'WIN OR GO HOME'}</span></div><div><div class="team-logo rival">${opp.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</div><h3>${opp.name.split(' ').slice(0,-1).join(' ').toUpperCase()}</h3><small>${opp.name.split(' ').at(-1).toUpperCase()} · ${opp.w}–${opp.l}</small></div></div><div class="match-note">${s.phase==='regular'?`${opp.rating>u.overall+5?'UNDERDOG TERRITORY':'A WINNABLE GAME'} <span>Opponent ${round(opp.rating)} OVR · Your team ${round(u.overall)} OVR</span>`:s.phase==='playoffs'?'PLAYOFF BERTH SECURED <span>Win three playoff games to become champion.</span>':'THE SEASON IS IN THE BOOKS <span>Ownership review, then the draft.</span>'}</div></div>${s.phase==='regular'?`<div class="panel strategy"><div class="panel-label">YOUR WEEKLY APPROACH <span>CHOOSE ONE</span></div><div class="plans">${[['youth','01','Develop youth','−4 game rating','Fast growth. Accept the mistakes.'],['balanced','02','Stay balanced','No rating modifier','Steady development and results.'],['win','03','Win now','+3 game rating','Protect the job. Slower growth.']].map(([id,n,title,tag,desc])=>`<button data-action="plan:${id}" class="plan ${s.plan===id?'selected':''}" aria-pressed="${s.plan===id}"><span>${n} <i>${s.plan===id?'●':'○'}</i></span><b>${title}</b><em>${tag}</em><small>${desc}</small></button>`).join('')}</div><div class="action-row"><small>A win adds $2M to next year.<br>A loss can move you up the draft.</small>${button('Simulate week '+(s.week+1)+' <span>→</span>','play',false,'primary')}</div></div>`:`<div class="panel action-row"><p>${s.phase==='playoffs'?['Wild card round','Semifinal','Championship game'][s.playoffRound]:'Your next chapter begins with the draft.'}</p>${button(s.phase==='playoffs'?'Play postseason →':'Owner review & draft →',s.phase==='playoffs'?'playoffs':'review',false,'primary')}</div>`}${resultView()}<div class="panel wire"><div class="panel-label">LEAGUE WIRE <span>RECENT ACTIVITY</span></div>${s.log.length?s.log.slice(0,5).map(l=>`<p><span>+</span>${l}</p>`).join(''):'<p><span>+</span>You inherited a rebuilding team. Ownership asks for two wins and a reason to believe.</p><p><span>+</span>Five rival franchises are also rebuilding. Watch the draft race.</p>'}</div>`;}
function resultView(){let r=s.result;if(!r)return '';return `<div class="panel result"><div class="panel-label">LAST RESULT <span class="${r.win?'green':'orange'}">${r.win?'WIN':'LOSS'}</span></div><div class="result-line"><strong>${r.us}<span>–</span>${r.them}</strong><div><h3>${r.headline}</h3><small>vs ${r.opp}</small></div></div><div class="quarter-row">${r.quarters.map((q,i)=>`<span>Q${i+1} <b>${q[0]}–${q[1]}</b></span>`).join('')}<span>FINAL <b>${r.us}–${r.them}</b></span></div><div class="reasons">${r.reasons.filter(r=>r[1]).map(([n,v])=>`<span>${n} <b class="${v<0?'green':'orange'}">${v>0?'+':''}${v} heat</b></span>`).join('')}</div></div>`;}
function roster(){return `<div class="panel"><div class="panel-label">BUILD YOUR CORE <span>${s.trained.length}/2 TRAINING SLOTS USED</span></div><p class="intro">Train for +2 OVR ($3M), up to each player's ceiling. Trade one veteran before week 7 for $5M and an extra draft selection; heat rises by ${Game.weightedHeat(s,5)}.</p><div class="roster-list">${s.roster.map((p,i)=>`<div class="player"><span class="position">${p.pos}</span><div class="player-name"><b>${p.name}</b><small>AGE ${p.age} · CEILING ${p.potential} · ${money(p.salary)}/YR · ${p.years}Y</small></div><strong class="rating">${round(p.rating)}</strong><div class="player-actions">${button(s.trained.includes(i)?'Trained ✓':'Train · $3M','train:'+i,s.phase!=='regular'||s.cash<3||s.trained.length>=2||s.trained.includes(i)||p.rating>=p.potential)}${button('Trade','trade:'+i,s.phase!=='regular'||s.week>=6||!!s.extraPick||p.rating<60,'subtle')}</div></div>`).join('')}</div></div>`;}
function market(){return `<div class="panel"><div class="panel-label">FREE AGENT MARKET <span>IMMEDIATE IMPACT</span></div><p class="intro">Sign a two-year contract and replace your current player at that position. Full first-year salary is paid now; the departing player's salary is not refunded. Rivals sign players every three weeks.</p>${s.market.map(p=>`<div class="player"><span class="position">${p.pos}</span><div class="player-name"><b>${p.name}</b><small>AGE ${p.age} · ${p.years}-YEAR CONTRACT · CEILING ${p.potential}</small></div><strong class="rating">${p.rating}</strong>${button('Sign · '+money(p.salary)+'/yr','sign:'+p.id,s.cash<p.salary||s.phase!=='regular')}</div>`).join('')||'<p>The market is empty. A new class arrives next season.</p>'}</div>`;}
function league(){return `<div class="panel"><div class="panel-label">THE RACE FOR TALENT <span>16 FRANCHISES</span></div><p class="intro">Worst record earns the first pick. Equal records use a fixed league-order tiebreaker. The top six teams by wins, then point differential, enter the playoffs.</p><div class="table-wrap"><table><thead><tr><th>PICK</th><th>FRANCHISE</th><th>W–L</th><th>OVR</th><th>OUTLOOK</th></tr></thead><tbody>${Game.draftOrder(s).map((t,i)=>`<tr class="${!t.id?'you':''}"><td>#${i+1}</td><td>${t.name}${!t.id?' <small>YOU</small>':''}</td><td>${t.w}–${t.l}</td><td>${round(t.id?t.rating:Game.units(s).overall)}</td><td>${t.mode}</td></tr>`).join('')}</tbody></table></div></div>`;}
function draftView(){return `<div class="panel"><div class="eyebrow">THE NEXT CHAPTER</div><h2>You’re on the clock.</h2><p>Selection ${s.draftTurn+1} of ${s.draftSlots.length} · Pick #${s.draftSlots[s.draftTurn]}. Drafting replaces your current player at that position. Rookie contracts are $3M per year for three years.</p>${s.draftTurn===0&&s.pick>=3&&!s.movedUp?`<div class="trade-offer"><b>Trade offer: move up two spots</b><p>A rival will exchange picks for $12M. Unlock two earlier prospects.</p>${button('Trade up · $12M','moveUp',s.cash<12)}</div>`:''}${s.prospects.slice(0,10).map(p=>`<div class="player"><span class="position">${p.pos}</span><div class="player-name"><b>${p.name}</b><small>BOARD #${p.rank} · POTENTIAL ${p.potential} · AGE 21</small></div><strong class="rating">${p.rating}</strong>${button('Draft →','draft:'+p.rank,false,'primary')}</div>`).join('')}</div>`;}
function ending(){return `<div class="panel ending"><div class="eyebrow">RUN COMPLETE</div><div class="trophy">${s.phase==='champion'?'🏆':'🔥'}</div><h2>${s.phase==='champion'?'From the bottom.<br>To the very top.':'The seat got too hot.'}</h2><p>${s.phase==='champion'?`You won the championship in ${s.season} season${s.season>1?'s':''}.`:`Ownership ended your tenure in season ${s.season}, after ${s.week} games. Rebuild, learn, run it back.`}</p><div class="end-stats"><span><b>${s.season}</b>SEASONS</span><span><b>${round(Game.units(s).overall)}</b>FINAL OVR</span><span><b>${s.history.reduce((a,h)=>a+h.w,0)+s.teams[0].w}</b>CAREER WINS</span></div>${button('Start a new tenure →','reset',false,'primary')}</div>${resultView()}`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;let [a,v]=b.dataset.action.split(':');notice='';if(a==='help'){$('#help').showModal();return;}if(a==='reset'){if(!confirm('Start a new run? Your current saved tenure will be replaced.'))return;s=Game.fresh();tab='office';}else if(a==='tab')tab=v;else if(a==='plan')s.plan=v;else if(a==='play')Game.play(s);else if(a==='playoffs')Game.playoffs(s);else if(a==='review')Game.review(s);else if(a==='moveUp'){Game.moveUp(s);notice='Trade accepted. Two earlier prospects are now on your board.';}else if(['train','sign','trade'].includes(a)){if(a==='trade'&&!confirm(`Trade this player for $5M and an extra draft selection? A 43 OVR replacement joins; heat rises by ${Game.weightedHeat(s,5)}.`))return;let ok=Game[a](s,Number(v));notice=ok?({train:'Training complete. Your player improved by up to 2 OVR.',sign:'Contract signed. Your new player is in the starting lineup.',trade:'Trade accepted. Future talent, at a cost today.'}[a]):'This move is no longer available.';}else if(a==='draft'){Game.draft(s,Number(v));tab='office';}save();render();});render();
